css:
.loader {
  position: relative;
  width: 50px;
  height: 52px;
}
.loader::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 8px;
  width: 4px;
  height: 100%;
  border-radius: 2px;
  background: #6366f1;
}
.loader::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 8px;
  width: 36px;
  height: 4px;
  border-radius: 2px;
  background: #6366f1;
}
.loader i {
  position: absolute;
  top: 6px;
  right: 8px;
  width: 2px;
  background: #c7d2fe;
  animation: cable 1.6s ease-in-out infinite;
}
.loader i::after {
  content: "";
  position: absolute;
  bottom: -10px;
  left: 50%;
  width: 14px;
  height: 10px;
  margin-left: -7px;
  border-radius: 2px;
  background: #4338ca;
}
@keyframes cable {
  0%, 100% { height: 14px; }
  50% { height: 34px; }
}
